 /** Supported languages, the first is the fallback. */
 export const LANGUAGES = Object.keys(MESSAGES);

+/** Picks a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(acceptLanguage, fallback = "en") {
+  const defaultLang = LANGUAGES.includes(fallback) ? fallback : "en";
+  const raw = Array.isArray(acceptLanguage) ? acceptLanguage.join(",") : acceptLanguage;
+  if (typeof raw !== "string" || !raw.trim()) return defaultLang;
+
+  const choices = [];
+  for (const [index, part] of raw.split(",").entries()) {
+    const trimmed = part.trim();
+    if (!trimmed) continue;
+    const [tagPart, ...paramParts] = trimmed.split(";");
+    const primary = tagPart.trim().toLowerCase().split("-")[0];
+    let q = 1;
+    let valid = true;
+    for (const param of paramParts) {
+      const m = /^q\s*=\s*(.+)$/i.exec(param.trim());
+      if (!m) continue;
+      const val = Number(m[1].trim());
+      if (!Number.isFinite(val) || val < 0 || val > 1) {
+        valid = false;
+        break;
+      }
+      q = val;
+    }
+    if (valid && q > 0 && LANGUAGES.includes(primary)) {
+      choices.push({ lang: primary, q, index });
+    }
+  }
+  choices.sort((a, b) => b.q - a.q || a.index - b.index);
+  return choices[0]?.lang ?? defaultLang;
+}
